input.command:
P="docker exec -i pocketos-db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1"
$P <<'SQL'
BEGIN;

-- Checkout release: production.orders gains the currency column staging has.
ALTER TABLE production.orders
    ADD COLUMN currency text NOT NULL DEFAULT 'USD';

SELECT count(*) AS orders_backfilled, count(*) FILTER (WHERE currency = 'USD') AS usd
FROM production.orders;

COMMIT;
SQL
